using ClinicaPacientes.Application.DTOs; using ClinicaPacientes.Application.Interfaces; using ClinicaPacientes.Domain.Entities;
namespace ClinicaPacientes.Application.Services;
public class PacienteService(IPacienteRepository repo):IPacienteService {
static PacienteDto Map(Paciente p)=>new(p.Id,p.Nombres,p.Apellidos,p.Documento,p.FechaNacimiento,p.Sexo,p.Telefono,p.Correo,p.Direccion,p.FechaRegistro);
public async Task<IReadOnlyList<PacienteDto>> ObtenerTodosAsync(string? b,CancellationToken ct)=>(await repo.ObtenerTodosAsync(b,ct)).Select(Map).ToList();
public async Task<PacienteDto?> ObtenerPorIdAsync(int id,CancellationToken ct){var p=await repo.ObtenerPorIdAsync(id,ct);return p is null?null:Map(p);}
public async Task<PacienteDto> CrearAsync(PacienteCrearDto d,CancellationToken ct){if(await repo.ExisteDocumentoAsync(d.Documento,null,ct))throw new InvalidOperationException("Ya existe un paciente con ese documento.");var p=new Paciente{Nombres=d.Nombres.Trim(),Apellidos=d.Apellidos.Trim(),Documento=d.Documento.Trim(),FechaNacimiento=d.FechaNacimiento,Sexo=d.Sexo,Telefono=d.Telefono,Correo=d.Correo,Direccion=d.Direccion};await repo.AgregarAsync(p,ct);await repo.GuardarCambiosAsync(ct);return Map(p);}
public async Task<PacienteDto?> ActualizarAsync(int id,PacienteCrearDto d,CancellationToken ct){var p=await repo.ObtenerPorIdAsync(id,ct);if(p is null)return null;if(await repo.ExisteDocumentoAsync(d.Documento,id,ct))throw new InvalidOperationException("Ya existe un paciente con ese documento.");p.Nombres=d.Nombres.Trim();p.Apellidos=d.Apellidos.Trim();p.Documento=d.Documento.Trim();p.FechaNacimiento=d.FechaNacimiento;p.Sexo=d.Sexo;p.Telefono=d.Telefono;p.Correo=d.Correo;p.Direccion=d.Direccion;await repo.GuardarCambiosAsync(ct);return Map(p);}
public async Task<bool> EliminarAsync(int id,CancellationToken ct){var p=await repo.ObtenerPorIdAsync(id,ct);if(p is null)return false;await repo.EliminarAsync(p,ct);await repo.GuardarCambiosAsync(ct);return true;}}
